/**
 * Split a Roznamcha entry's STORED lines into the DR side and the CR side of its voucher.
 *
 * The voucher mirrors the entry exactly as it was stored: a line with debit > 0 is printed on the DR
 * side, a line with credit > 0 on the CR side, and nothing is added. A cash entry is stored with ONE
 * line (either a DR or a CR), so its voucher shows one side only. A posting generated by a purchase,
 * sale or expense module is stored with both legs, so its voucher shows both.
 */
export type VoucherLegSource = {
  debit?: unknown;
  credit?: unknown;
  account_number?: string | null;
  account_code?: string | null;
  description?: string | null;
  accounts?: { name?: string | null } | null;
  ledgers?: { name?: string | null } | null;
};

export type VoucherLeg = {
  code: string | null;
  name: string | null;
  amount: number;
  narration: string | null;
};

export function voucherLegsFromLines(lines: readonly VoucherLegSource[]): { drLines: VoucherLeg[]; crLines: VoucherLeg[] } {
  const toLeg = (line: VoucherLegSource, amount: number): VoucherLeg => ({
    code: line.account_number || line.account_code || null,
    name: line.accounts?.name || line.ledgers?.name || null,
    amount,
    narration: line.description || null,
  });
  return {
    drLines: lines.filter((l) => Number(l.debit || 0) > 0).map((l) => toLeg(l, Number(l.debit || 0))),
    crLines: lines.filter((l) => Number(l.credit || 0) > 0).map((l) => toLeg(l, Number(l.credit || 0))),
  };
}
